mapper.select:
SELECT id, content, created_at FROM post_comment WHERE post_id = #{postId} AND deleted=false
AND id < #{cursor}
ORDER BY id DESC LIMIT #{size}

mapper.update:
UPDATE post_comment
SET content = #{content},
    updated_at = NOW()
WHERE id = #{commentId}
  AND post_id = #{postId}
  AND member_id = #{memberId}
  AND deleted = false

UPDATE post_comment
SET deleted    = true,
    updated_at = NOW()
WHERE id = #{commentId}
  AND post_id = #{postId}
  AND member_id = #{memberId}
  AND deleted = false

UPDATE post_comment
SET deleted    = false,
    updated_at = NOW()
WHERE id = #{commentId}
  AND post_id = #{postId}
  AND member_id = #{memberId}
  AND deleted = true
